  // verdict here (§ Display: only added sugar has a threshold at all).
  field("added_sugar_g", "added_sugar"),
  field("fiber_g", "fiber"),
  field("sodium_mg", "sodium"),
  field("entry_count", "entries"),
  field("expenditure_kcal", "burned"),
  field("net_kcal", "net")
